const fs=require("fs");
const html=fs.readFileSync("./perf-reports/bookshelf_2026-07-29_09-54-33.html","utf8");
const m=html.match(/window\.__LIGHTHOUSE_JSON__\s*=\s*(\{[\s\S]*?\});\s*<\/script>/);
const lhr=JSON.parse(m[1]);
console.log("URL:",lhr.finalDisplayedUrl);
for(const [k,c] of Object.entries(lhr.categories)) console.log(c.title+":",Math.round(c.score*100));
console.log("\n--- Metrics ---");
for(const id of ["first-contentful-paint","largest-contentful-paint","total-blocking-time","cumulative-layout-shift","speed-index"]){
  const a=lhr.audits[id]; if(a) console.log(a.title+":",a.displayValue);
}
console.log("\n--- Failing / flagged audits ---");
for(const [id,a] of Object.entries(lhr.audits)){
  if(a.score!==null&&a.score<1&&a.scoreDisplayMode!=="informative"&&a.scoreDisplayMode!=="notApplicable"&&a.scoreDisplayMode!=="manual"){
    console.log("*",a.title,"| score:",a.score,"|",a.displayValue||"");
  }
}
'

